import re


def eval_expression(expr):
    # トークン化
    tokens = []
    i = 0
    number_pattern = re.compile(r"(?:\d+(?:\.\d*)?|\.\d+)")

    while i < len(expr):
        if expr[i].isspace():
            i += 1
            continue

        if expr[i] in "+-*/()":
            tokens.append(expr[i])
            i += 1
            continue

        match = number_pattern.match(expr, i)
        if match:
            text = match.group()
            value = float(text) if "." in text else int(text)
            tokens.append(("number", value))
            i = match.end()
            continue

        raise ValueError(f"不正な文字です: {expr[i]!r}")

    tokens.append("EOF")
    pos = 0

    def current():
        return tokens[pos]

    def consume(expected=None):
        nonlocal pos
        token = current()

        if expected is not None and token != expected:
            raise ValueError(f"{expected!r} が必要ですが、{token!r} が見つかりました")

        pos += 1
        return token

    # expr := term (("+" | "-") term)*
    def parse_expression():
        value = parse_term()

        while current() in ("+", "-"):
            operator = consume()
            right = parse_term()

            if operator == "+":
                value += right
            else:
                value -= right

        return value

    # term := unary (("*" | "/") unary)*
    def parse_term():
        value = parse_unary()

        while current() in ("*", "/"):
            operator = consume()
            right = parse_unary()

            if operator == "*":
                value *= right
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                value /= right

        return value

    # unary := ("+" | "-") unary | primary
    def parse_unary():
        if current() == "+":
            consume("+")
            return parse_unary()

        if current() == "-":
            consume("-")
            return -parse_unary()

        return parse_primary()

    # primary := number | "(" expr ")"
    def parse_primary():
        token = current()

        if isinstance(token, tuple) and token[0] == "number":
            consume()
            return token[1]

        if token == "(":
            consume("(")
            value = parse_expression()
            consume(")")
            return value

        raise ValueError(f"数値または括弧が必要ですが、{token!r} が見つかりました")

    result = parse_expression()

    if current() != "EOF":
        raise ValueError(f"予期しないトークンです: {current()!r}")

    return result
